<?php if(!isset($filters,$errors)) { http_response_code(404); exit; } ?>
<!doctype html><html lang="et"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" type="image/png" href="favicon.png?v=1"><title>Pearaamat</title>
<style>*{box-sizing:border-box}body{max-width:1280px;margin:32px auto;padding:0 22px;background:#f4f7fb;color:#243447;font:15px/1.5 Arial,sans-serif}h1,h2{color:#17324d;margin-top:0}h1{margin-bottom:5px}h2{font-size:20px}.topbar{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:24px}.muted{color:#68798b;font-size:13px}.card{background:#fff;border:1px solid #dce3ec;border-radius:12px;padding:22px;margin:18px 0}.filters{display:flex;flex-wrap:wrap;gap:14px;align-items:end}label{display:grid;gap:6px;font-weight:600;font-size:14px}input,select{min-height:42px;padding:9px 11px;border:1px solid #b8c4d1;border-radius:7px;background:white;color:inherit;font:inherit}select{max-width:350px}button,.button,summary{display:inline-block;min-height:42px;padding:10px 16px;border:0;border-radius:7px;background:#1769aa;color:white;font:inherit;font-weight:600;text-decoration:none;cursor:pointer}.secondary{background:#657789}.download{position:relative;display:inline-block}.download summary{list-style:none}.download summary::-webkit-details-marker{display:none}.download[open] summary{background:#0f4f83}.download-menu{position:absolute;z-index:10;right:0;top:48px;min-width:200px;padding:6px;background:white;border:1px solid #d5deea;border-radius:9px;box-shadow:0 8px 24px #17324d20}.download-menu button{display:block;text-align:left;width:100%;background:white;color:#234562;border-radius:5px}.download-menu button:hover{background:#edf4fb}.summary{display:flex;gap:30px;flex-wrap:wrap}.summary strong{display:block;color:#17324d;font-size:22px}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:11px 12px;border-bottom:1px solid #e4eaf2;text-align:left;vertical-align:top}th{background:#edf2f8;color:#17324d;font-size:13px}.num{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}.totals{background:#f0f4f8;font-weight:bold}a{color:#1769aa}.small{display:block;font-size:12px;color:#788699}.error{background:#fff0f0;color:#9b2424;padding:14px;border:1px solid #edc4c4;border-radius:8px}.empty{color:#68798b;padding:14px 0}input:disabled{background:#f0f3f6;color:#8995a3}@media(max-width:700px){body{padding:0 13px;margin-top:22px}.topbar{align-items:flex-start}.topbar .button{font-size:13px}.filters{align-items:stretch;flex-direction:column}select{max-width:none;width:100%}.filters button{width:100%}.summary{gap:20px}.summary strong{font-size:19px}.download-menu{right:0}th,td{padding:9px}.card{padding:17px}}</style></head><body>
<header class="topbar"><div><h1>Pearaamat</h1><div class="muted"><?= ledgerHtml($report['company']['name']??'') ?><?php if($report): ?> · <?= ledgerHtml((string)$report['company']['registry_code']) ?><?php endif; ?></div></div><a class="button secondary" href="index.php">Avalehele</a></header>
<form method="get" id="ledger-filters" class="card filters">
<label>Konto<select name="account_id"><option value="">Kõik kontod</option><?php foreach($report['catalog']??[] as $account): ?><option value="<?= (int)$account['id'] ?>" <?= $filters['account_id']===(int)$account['id']?'selected':'' ?>><?= ledgerHtml($account['code'].' — '.$account['name'].(!$account['is_active']?' (mitteaktiivne)':'')) ?></option><?php endforeach; ?></select></label>
<label>Periood<select name="scope" id="ledger-scope"><option value="range" <?= $filters['scope']==='range'?'selected':'' ?>>Valitud periood</option><option value="all" <?= $filters['scope']==='all'?'selected':'' ?>>Kogu ajalugu</option></select></label>
<label>Alates<input type="date" name="start_date" required value="<?= ledgerHtml($filters['start_date']??(substr(ledgerToday(),0,4).'-01-01')) ?>" <?= $filters['scope']==='all'?'disabled':'' ?>></label>
<label>Kuni<input type="date" name="end_date" required value="<?= ledgerHtml($filters['end_date']??ledgerToday()) ?>" <?= $filters['scope']==='all'?'disabled':'' ?>></label>
<button type="submit">Näita</button><details class="download"><summary>Lae alla ▾</summary><div class="download-menu"><button type="submit" name="download" value="csv">CSV</button><button type="submit" name="download" value="pdf">PDF</button><button type="submit" name="download" value="xlsx">XLSX</button></div></details>
</form><p class="muted">Terve pearaamatu jaoks vali „Kõik kontod” ja „Kogu ajalugu”. Allalaadimine kasutab vormis valitud tingimusi ning sisaldab kõiki nendele vastavaid kinnitatud kanderidu, ka mitteaktiivsetel kontodel.</p>
<?php foreach($errors as $error): ?><p class="error" role="alert"><?= ledgerHtml($error) ?></p><?php endforeach; ?>
<?php if($report): ?><section class="card"><h2><?= ledgerHtml(ledgerPeriod($report)) ?></h2><div class="summary"><div><span class="muted">Kontosid</span><strong><?= count($report['accounts']) ?></strong></div><div><span class="muted">Kanderidu</span><strong><?= $report['row_count'] ?></strong></div><div><span class="muted">Perioodi deebet</span><strong><?= ledgerHtml(ledgerMoney($report['debit'])) ?></strong></div><div><span class="muted">Perioodi kreedit</span><strong><?= ledgerHtml(ledgerMoney($report['credit'])) ?></strong></div></div></section>
<?php if(!$report['accounts']): ?><section class="card empty">Valitud tingimustel kandeid ega algsaldosid ei ole.</section>
<?php elseif($filters['account_id']===null): ?>
<section class="card"><h2>Kontode kokkuvõte</h2><p class="muted">Kontonimele vajutades näed selle kanderidu. CSV, PDF ja XLSX sisaldavad kogu valiku kanderidu koos alg- ja lõppsaldodega.</p><div class="table-wrap"><table><thead><tr><th>Konto</th><th>Saldo suund</th><th class="num">Algsaldo</th><th class="num">Deebet</th><th class="num">Kreedit</th><th class="num">Lõppsaldo</th></tr></thead><tbody>
<?php foreach($report['accounts'] as $account): ?><tr><td><a href="ledger.php?<?= ledgerHtml(http_build_query(array_filter(array_replace($filters,['account_id'=>$account['id']]),static fn($v):bool=>$v!==null))) ?>"><?= ledgerHtml($account['code'].' — '.$account['name']) ?></a><?php if(!$account['is_active']): ?><span class="small">Mitteaktiivne konto</span><?php endif; ?></td><td><?= $account['sign']===1?'Deebet':'Kreedit' ?></td><td class="num"><?= ledgerHtml(ledgerMoney($account['opening'])) ?></td><td class="num"><?= ledgerHtml(ledgerMoney($account['debit'])) ?></td><td class="num"><?= ledgerHtml(ledgerMoney($account['credit'])) ?></td><td class="num"><?= ledgerHtml(ledgerMoney($account['closing'])) ?></td></tr><?php endforeach; ?>
</tbody><tfoot><tr><th colspan="3">Perioodi kokku</th><th class="num"><?= ledgerHtml(ledgerMoney($report['debit'])) ?></th><th class="num"><?= ledgerHtml(ledgerMoney($report['credit'])) ?></th><th></th></tr></tfoot></table></div></section>
<?php else: ?>
<section class="card"><h2><?= ledgerHtml($report['accounts'][0]['code'].' — '.$report['accounts'][0]['name']) ?></h2><p class="muted">Saldo suund: <?= $report['accounts'][0]['sign']===1?'deebet':'kreedit' ?>. Summad eurodes.</p><div class="table-wrap"><table><thead><tr><th>Kuupäev</th><th>Kanne</th><th>Dokumendi nr</th><th>Kirjeldus</th><th class="num">Deebet</th><th class="num">Kreedit</th><th class="num">Saldo</th></tr></thead><tbody>
<?php foreach(ledgerRecords($pdo,$report) as $record): ?>
<?php if($record['kind']==='entry'): ?><tr><td><?= ledgerHtml($record['date']) ?></td><td><a href="entry.php?id=<?= $record['entry_id'] ?>">#<?= $record['entry_id'] ?></a><span class="small">Rida #<?= $record['line_id'] ?></span></td><td><?= ledgerHtml($record['document']) ?><?php if($record['corrected_document']!==''): ?><span class="small">Parandab: <?= ledgerHtml($record['corrected_document']) ?></span><?php endif; ?></td><td><?= ledgerHtml($record['line_description']?:$record['entry_description']) ?><?php if($record['line_description'] && $record['line_description']!==$record['entry_description']): ?><span class="small"><?= ledgerHtml($record['entry_description']) ?></span><?php endif; ?></td><td class="num"><?= ledgerHtml(ledgerMoney($record['debit'])) ?></td><td class="num"><?= ledgerHtml(ledgerMoney($record['credit'])) ?></td><td class="num"><?= ledgerHtml(ledgerMoney($record['balance'])) ?></td></tr>
<?php else: ?><tr class="totals"><td colspan="4"><?= ['opening'=>'Algsaldo enne perioodi','summary'=>'Perioodi kokku','closing'=>'Lõppsaldo'][$record['kind']] ?></td><td class="num"><?= $record['debit']===null?'':ledgerHtml(ledgerMoney($record['debit'])) ?></td><td class="num"><?= $record['credit']===null?'':ledgerHtml(ledgerMoney($record['credit'])) ?></td><td class="num"><?= $record['kind']==='summary'?'':ledgerHtml(ledgerMoney($record['balance'])) ?></td></tr><?php endif; ?>
<?php endforeach; ?></tbody></table></div></section>
<?php endif; ?><p class="muted">Vara ja kulu saldo: deebet miinus kreedit. Kohustuse, omakapitali ja tulu saldo: kreedit miinus deebet. Mustandid ja tühistatud kanded ei sisaldu.</p><?php endif; ?>
<script>(()=>{const scope=document.getElementById('ledger-scope');function update(){document.querySelectorAll('[name="start_date"],[name="end_date"]').forEach(input=>{input.disabled=scope.value==='all';});}scope.addEventListener('change',update);update();document.getElementById('ledger-filters').addEventListener('submit',()=>{const menu=document.querySelector('.download');if(menu)menu.open=false;});document.addEventListener('click',event=>{const menu=document.querySelector('.download');if(menu&&!menu.contains(event.target))menu.open=false;});})();</script></body></html>
